RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

/* 重新配置前先复位，清掉上一次的残留设置 */
DMA_DeInit(DMA1_Channel4);   /* USART1_TX 固定用 DMA1_Channel4 */
DMA_Init(DMA1_Channel4, &DMA_InitStructure);

DMA_InitTypeDef DMA_InitStructure;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

/* USART1_TX 硬件固定映射到 DMA1_Channel4，不能乱选 */
DMA_DeInit(DMA1_Channel4);
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&USART1->DR;
DMA_InitStructure.DMA_MemoryBaseAddr     = (uint32_t)txBuffer;
DMA_InitStructure.DMA_DIR                = DMA_DIR_PeripheralDST;   /* 内存 -> 外设 */
DMA_InitStructure.DMA_BufferSize         = 128;
DMA_InitStructure.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc          = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;
DMA_InitStructure.DMA_MemoryDataSize     = DMA_MemoryDataSize_Byte;
DMA_InitStructure.DMA_Mode               = DMA_Mode_Normal;
DMA_InitStructure.DMA_Priority           = DMA_Priority_Medium;
DMA_InitStructure.DMA_M2M                = DMA_M2M_Disable;
DMA_Init(DMA1_Channel4, &DMA_InitStructure);

/* 打开外设侧的 DMA 请求，再使能通道 */
USART_DMACmd(USART1, USART_DMAReq_Tx, ENABLE);
DMA_Cmd(DMA1_Channel4, ENABLE);

DMA_InitTypeDef DMA_InitStructure;

DMA_StructInit(&DMA_InitStructure);
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&ADC1->DR;  /* 默认是 0xFFFFFFFF，必须改 */
DMA_InitStructure.DMA_MemoryBaseAddr     = (uint32_t)adcBuf;
DMA_InitStructure.DMA_BufferSize         = 256;
DMA_InitStructure.DMA_Mode               = DMA_Mode_Circular;
DMA_Init(DMA1_Channel1, &DMA_InitStructure);

/* Normal 模式：每次传输都要重装计数并重新使能 */
void DMA1_Channel4_SendAgain(uint16_t len)
{
  DMA_Cmd(DMA1_Channel4, DISABLE);              /* 必须先在关闭状态下改计数 */
  DMA_SetCurrDataCounter(DMA1_Channel4, len);   /* 重装数据个数 */
  DMA_ClearFlag(DMA1_FLAG_TC4 | DMA1_FLAG_GL4); /* 清旧标志 */
  DMA_Cmd(DMA1_Channel4, ENABLE);               /* 重新启动 */
}

DMA_ITConfig(DMA1_Channel4, DMA_IT_TC, ENABLE);

NVIC_InitStructure.NVIC_IRQChannel = DMA1_Channel4_IRQn;   /* 注意 4~7 共用一个向量 */
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

/* 4~7 共用一个服务函数，必须逐条判断是哪个通道 */
void DMA1_Channel4_7_IRQHandler(void)
{
  if (DMA_GetITStatus(DMA1_IT_TC4) != RESET)
  {
    DMA_ClearITPendingBit(DMA1_IT_TC4);   /* 不清就会反复进中断 */
    /* 标记一次发送结束 */
  }
}

/* 变长发送：每次发送前重装长度 */
void USART1_DMASend(uint8_t *buf, uint16_t len)
{
  while (DMA_GetCurrDataCounter(DMA1_Channel4) != 0) { }  /* 等上一次发完 */

  DMA_Cmd(DMA1_Channel4, DISABLE);
  DMA_SetCurrDataCounter(DMA1_Channel4, len);   /* 重装长度 */
  DMA1_Channel4->CMAR = (uint32_t)buf;          /* 缓冲区变了要改内存地址 */
  DMA_ClearFlag(DMA1_FLAG_TC4 | DMA1_FLAG_GL4);
  DMA_Cmd(DMA1_Channel4, ENABLE);
}

/* USART1 + DMA 接收不定长数据：靠空闲中断判断一帧结束 */
#define RX_BUF_SIZE 128
uint8_t rxBuf[RX_BUF_SIZE];

void USART1_IRQHandler(void)
{
  if (USART_GetITStatus(USART1, USART_IT_IDLE) != RESET)
  {
    (void)USART1->SR; (void)USART1->DR;   /* 读 SR 再读 DR 清空闲标志 */

    /* 收到的长度 = 总长度 - 剩余未传个数 */
    uint16_t received = RX_BUF_SIZE - DMA_GetCurrDataCounter(DMA1_Channel5);

    /* 处理 rxBuf[0..received-1] */

    /* 重新开始接收 */
    DMA_Cmd(DMA1_Channel5, DISABLE);
    DMA_SetCurrDataCounter(DMA1_Channel5, RX_BUF_SIZE);
    DMA_Cmd(DMA1_Channel5, ENABLE);
  }
}

/* 轮询等一块数据搬完（不用中断） */
while (DMA_GetFlagStatus(DMA1_FLAG_TC4) == RESET) { }
DMA_ClearFlag(DMA1_FLAG_TC4 | DMA1_FLAG_GL4);   /* 必须清，否则下次判断直接成立 */

/* 之后才能安全地做收尾，例如拉高片选或切换缓冲区 */
GPIO_SetBits(GPIOA, GPIO_Pin_4);

/* 重新发起一次传输前，先清干净旧标志 */
DMA_ClearFlag(DMA1_FLAG_GL4 | DMA1_FLAG_TC4 | DMA1_FLAG_HT4 | DMA1_FLAG_TE4);

DMA_Cmd(DMA1_Channel4, DISABLE);
DMA_SetCurrDataCounter(DMA1_Channel4, len);
DMA_Cmd(DMA1_Channel4, ENABLE);

/* Channel4~Channel7 共用一个向量，必须逐条判断 */
void DMA1_Channel4_7_IRQHandler(void)
{
  if (DMA_GetITStatus(DMA1_IT_TC4) != RESET)
  {
    DMA_ClearITPendingBit(DMA1_IT_TC4);
    /* USART1 发送完成 */
  }
  if (DMA_GetITStatus(DMA1_IT_TC5) != RESET)
  {
    DMA_ClearITPendingBit(DMA1_IT_TC5);
    /* USART1 接收完成 */
  }
}

void DMA1_Channel1_IRQHandler(void)
{
  if (DMA_GetITStatus(DMA1_IT_TC1) != RESET)
  {
    DMA_ClearITPendingBit(DMA1_IT_TC1);   /* 先清标志，再处理数据 */
    /* 处理 ADC 采集到的缓冲区 */
  }
}
